def sumDigitArrays(nums):
    width = max(len(row) for row in nums)
    cols = [0] * width
    for row in nums:
        shift = width - len(row)
        for i, d in enumerate(row):
            cols[shift + i] += d
    res = []
    carry = 0
    for p in range(width - 1, -1, -1):
        carry, d = divmod(cols[p] + carry, 10)
        res.append(d)
    while carry:
        carry, d = divmod(carry, 10)
        res.append(d)
    while len(res) > 1 and res[-1] == 0:
        res.pop()
    res.reverse()
    return res
